
class Solution {
public:
    int maximumSaleItems(vector<vector<int>>& items, int budget) {
        int n = items.size();

        vector<int> bonus(n, 0);

        // Calculate free copies generated by buying each item
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j &&
                    items[j][0] % items[i][0] == 0) {
                    bonus[i]++;
                }
            }
        }

        // dp[i][w] = maximum items using first i items
        // with spending at most w
        vector<vector<int>> dp(n + 1,
                               vector<int>(budget + 1, 0));

        for (int i = 1; i <= n; i++) {
            int cost = items[i - 1][1];
            int val = bonus[i - 1];

            for (int w = 0; w <= budget; w++) {

                // Do not buy this item
                dp[i][w] = dp[i - 1][w];

                if (w >= cost) {

                    // Buy additional copies (unbounded)
                    dp[i][w] = max(dp[i][w],
                                   dp[i][w - cost] + 1);

                    // Buy the first copy (gets free copies)
                    dp[i][w] = max(dp[i][w],
                                   dp[i - 1][w - cost] + 1 + val);
                }
            }
        }

        return dp[n][budget];
    }
};
